CREATE TEMPORARY VIEW user_exp_${grass_region_without_quote} AS
SELECT
    user_id
    ,exp_group_id
FROM
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND is_assignment_log = 1
    AND is_search_whitelist = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_outlier_broad_${grass_region_without_quote} AS 
SELECT
    if(feature_group = 'all', '__ALL__', feature_group) AS feature_group
    ,max(abs) as abs_999
FROM 
    srdi_mart.ads_sr_data_warehouse_platform_feature_group_ads_outlier_1d
WHERE 
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND outlier_type = 'broad_ads_abs'
    AND percentile = 0.999
group by 
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_outlier_direct_${grass_region_without_quote} AS 
